export default function Section() {
  return (
    <section className="bg-surface pt-4 pb-10 md:pt-6 md:pb-16">
      <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
        <nav aria-label="Breadcrumb" className="mb-3 md:mb-5">
          <Breadcrumbs className="flex flex-wrap items-center gap-x-1 text-base">
            {b => (
              <span className="inline-flex items-center gap-1">
                {b.url && !b.current ? (
                  <Link
                    href={b.url}
                    className="inline-flex min-h-11 items-center rounded-full px-2 font-semibold text-foreground-secondary transition-colors hover:bg-primary-50 hover:text-primary-700"
                  >
                    {b.name}
                  </Link>
                ) : (
                  <span
                    aria-current="page"
                    className="inline-flex min-h-11 items-center px-2 font-semibold text-primary-700"
                  >
                    {b.name}
                  </span>
                )}
                {!b.current && (
                  <Icon name="chevron-right" size="sm" className="text-foreground-muted" />
                )}
              </span>
            )}
          </Breadcrumbs>
        </nav>

        <Category>
          {c => (
            <div className="relative">
              <div className="grid overflow-hidden rounded-3xl bg-primary-700 shadow-md">
                {c.image && (
                  <div className="col-start-1 row-start-1">
                    <div className="md:hidden">
                      <Image
                        src={c.mobileImage || c.image}
                        alt={c.name}
                        aspect="4:5"
                        fit="cover"
                        sizes="100vw"
                        priority
                      />
                    </div>
                    <div className="hidden md:block">
                      <Image
                        src={c.image}
                        alt={c.name}
                        aspect="21:9"
                        fit="cover"
                        sizes="(min-width: 1280px) 1280px, 100vw"
                        priority
                      />
                    </div>
                  </div>
                )}

                {c.image && (
                  <div
                    aria-hidden="true"
                    className="col-start-1 row-start-1 bg-gradient-to-t from-secondary-900/90 via-secondary-900/40 to-transparent md:bg-gradient-to-tr md:from-secondary-900/85 md:via-secondary-900/30"
                  />
                )}

                {!c.image && (
                  <div aria-hidden="true" className="relative col-start-1 row-start-1">
                    <div className="absolute -right-16 -top-16 h-56 w-56 rounded-full bg-accent-400 md:h-80 md:w-80" />
                    <div className="absolute -bottom-20 right-1/4 h-48 w-48 rounded-full bg-primary-500 md:h-64 md:w-64" />
                    <div className="absolute left-1/2 top-8 h-10 w-10 rotate-12 rounded-2xl bg-accent-300" />
                  </div>
                )}

                <div className="relative z-10 col-start-1 row-start-1 flex min-h-80 flex-col justify-end self-end p-5 pb-14 sm:p-8 sm:pb-16 md:min-h-96 lg:p-12 lg:pb-20">
                  {c.parentName && c.parentUrl && (
                    <Link
                      href={c.parentUrl}
                      className="mb-4 inline-flex min-h-11 w-fit -rotate-2 items-center gap-2 rounded-full bg-accent-400 px-5 font-semibold text-secondary-900 shadow-md transition-transform hover:rotate-0"
                    >
                      <Icon name="arrow-left" size="sm" />
                      {c.parentName}
                    </Link>
                  )}

                  <h1 className="max-w-3xl break-words font-display text-4xl leading-none text-white sm:text-5xl lg:text-7xl">
                    {c.name}
                  </h1>

                  {c.tagline && (
                    <p className="mt-4 max-w-2xl text-lg font-semibold text-accent-300 md:text-xl">
                      {c.tagline}
                    </p>
                  )}

                  {c.description && (
                    <p className="mt-3 max-w-xl text-base leading-relaxed text-white line-clamp-3 md:line-clamp-none md:text-lg">
                      {c.description}
                    </p>
                  )}
                </div>
              </div>

              {c.productCount > 0 && (
                <div className="absolute -top-3 right-3 z-20 flex h-24 w-24 rotate-6 flex-col items-center justify-center rounded-full bg-accent-400 text-center text-secondary-900 shadow-md sm:right-6 md:-top-5 md:h-28 md:w-28">
                  <span className="font-display text-2xl leading-none md:text-3xl">{c.productCount}</span>
                  <span className="mt-1 text-xs font-semibold uppercase tracking-wide">to explore</span>
                </div>
              )}

              <Reveal effect="fade-up" delay={0.1}>
                <SubCategories className="relative z-10 mx-3 -mt-8 flex flex-wrap gap-2 rounded-3xl border border-border-default bg-surface p-3 shadow-md sm:mx-6 sm:gap-3 sm:p-4 md:mx-10 lg:-mt-10">
                  {s => (
                    <Link
                      href={s.url}
                      className="group inline-flex min-h-11 items-center gap-2 rounded-full bg-primary-50 px-5 py-2 text-base font-semibold text-primary-700 transition-all hover:-rotate-2 hover:bg-primary-700 hover:text-white"
                    >
                      {s.name}
                      {s.productCount > 0 && (
                        <span className="inline-flex min-w-7 items-center justify-center rounded-full bg-accent-400 px-2 text-sm font-bold text-secondary-900">
                          {s.productCount}
                        </span>
                      )}
                    </Link>
                  )}
                </SubCategories>
              </Reveal>
            </div>
          )}
        </Category>
      </div>
    </section>
  )
}

export default function Section() {
  return (
    <section className="relative overflow-hidden bg-primary-50">
      <div aria-hidden="true" className="pointer-events-none absolute -right-16 -top-16 h-56 w-56 rounded-full bg-accent-200 md:h-80 md:w-80" />
      <div aria-hidden="true" className="pointer-events-none absolute -bottom-20 left-1/3 h-40 w-40 rounded-full bg-primary-100 md:h-64 md:w-64" />

      <div className="relative mx-auto max-w-6xl px-4 py-10 sm:px-6 md:py-16">
        <nav aria-label="Breadcrumb" className="mb-8 md:mb-12">
          <Breadcrumbs className="flex flex-wrap items-center gap-x-1 gap-y-1 text-sm text-foreground-secondary">
            {(c) => (
              <span className="inline-flex items-center gap-1">
                {c.url && !c.current ? (
                  <Link
                    href={c.url}
                    className="inline-flex min-h-11 items-center rounded-full px-2 font-medium hover:bg-primary-100 hover:text-primary-700"
                  >
                    {c.name}
                  </Link>
                ) : (
                  <span aria-current="page" className="inline-flex min-h-11 items-center rounded-full bg-white px-3 font-semibold text-primary-700 shadow-sm">
                    {c.name}
                  </span>
                )}
                {!c.current && <Icon name="chevron-right" size="xs" className="text-foreground-muted" />}
              </span>
            )}
          </Breadcrumbs>
        </nav>

        <Brand>
          {(b) => (
            <div className="grid grid-cols-1 items-center gap-12 md:grid-cols-12 md:gap-10 lg:gap-16">
              <div className="relative mx-auto w-full max-w-xs sm:max-w-sm md:col-span-5 md:max-w-none">
                <div aria-hidden="true" className="absolute inset-0 rotate-3 rounded-3xl bg-accent-400 shadow-md" />
                <div aria-hidden="true" className="absolute inset-0 -rotate-3 rounded-3xl border-4 border-dashed border-primary-300" />

                <div className="relative -rotate-1 rounded-3xl bg-white p-6 shadow-xl sm:p-10">
                  {b.logo ? (
                    <Image
                      src={b.logo}
                      alt={b.name}
                      aspect="1:1"
                      fit="contain"
                      priority={true}
                      sizes="(min-width: 768px) 40vw, 80vw"
                      className="rounded-3xl"
                    />
                  ) : (
                    <div className="flex aspect-square items-center justify-center rounded-3xl bg-primary-100 p-6">
                      <span className="text-center font-display text-3xl leading-tight text-primary-700 sm:text-4xl">
                        {b.name}
                      </span>
                    </div>
                  )}
                </div>

                <span className="absolute -left-3 -top-4 inline-flex -rotate-6 items-center gap-1.5 rounded-full bg-primary-700 px-4 py-2 text-sm font-semibold text-white shadow-md">
                  <Icon name="sparkles" size="sm" className="text-white" />
                  Meet the maker
                </span>

                {b.productCount > 0 && (
                  <span className="absolute -bottom-5 -right-2 inline-flex rotate-3 items-center gap-1.5 rounded-full bg-secondary-900 px-4 py-2 text-sm font-semibold text-white shadow-md">
                    <Icon name="shopping-bag" size="sm" className="text-white" />
                    {b.productCount} to explore
                  </span>
                )}
              </div>

              <div className="md:col-span-7">
                {b.tagline && (
                  <p className="mb-4 inline-flex rotate-1 rounded-full bg-accent-500 px-4 py-1.5 text-sm font-semibold text-secondary-900 shadow-sm">
                    {b.tagline}
                  </p>
                )}

                <h1 className="font-display text-4xl leading-none text-foreground sm:text-5xl lg:text-6xl">
                  {b.name}
                </h1>

                {b.description && (
                  <p className="mt-5 max-w-xl text-base leading-relaxed text-foreground-secondary line-clamp-5 md:text-lg">
                    {b.description}
                  </p>
                )}

                {(b.founded || b.origin || b.headquarters) && (
                  <dl className="mt-6 flex flex-wrap gap-3">
                    {b.founded && (
                      <div className="-rotate-1 rounded-2xl bg-white px-4 py-2 shadow-md">
                        <dt className="text-xs font-semibold uppercase tracking-wide text-foreground-muted">Since</dt>
                        <dd className="font-display text-lg text-primary-700">{b.founded}</dd>
                      </div>
                    )}
                    {b.origin && (
                      <div className="rotate-1 rounded-2xl bg-white px-4 py-2 shadow-md">
                        <dt className="text-xs font-semibold uppercase tracking-wide text-foreground-muted">From</dt>
                        <dd className="font-display text-lg text-primary-700">{b.origin}</dd>
                      </div>
                    )}
                    {b.headquarters && (
                      <div className="-rotate-1 rounded-2xl bg-white px-4 py-2 shadow-md">
                        <dt className="text-xs font-semibold uppercase tracking-wide text-foreground-muted">Based in</dt>
                        <dd className="font-display text-lg text-primary-700">{b.headquarters}</dd>
                      </div>
                    )}
                  </dl>
                )}

                <div className="mt-8 flex flex-wrap items-center gap-3">
                  {b.website && (
                    <Link
                      href={b.website}
                      target="_blank"
                      className="inline-flex min-h-12 items-center gap-2 rounded-full bg-primary-700 px-6 py-3 text-base font-semibold text-white shadow-md transition hover:-translate-y-0.5 hover:bg-primary-800"
                    >
                      Visit their website
                      <Icon name="arrow-up-right" size="sm" className="text-white" />
                    </Link>
                  )}
                  {b.socials &&
                    b.socials.map((s, i) => (
                      <Link
                        key={i}
                        href={s.href}
                        target="_blank"
                        className="inline-flex min-h-12 items-center gap-2 rounded-full border-2 border-primary-700 bg-white px-5 py-2.5 text-base font-semibold text-primary-700 transition hover:-translate-y-0.5 hover:bg-primary-100"
                      >
                        {s.label}
                        <Icon name="arrow-up-right" size="xs" className="text-primary-700" />
                      </Link>
                    ))}
                </div>
              </div>
            </div>
          )}
        </Brand>
      </div>
    </section>
  )
}
